local P={"F6","F7";"F8";"F9";"F10","F11","F12"}function P8BA6426E.NormalizeActionKey(P)if type(P)~="string"then return nil end local j=P:upper()local Y={}while true do local P,X=j:match("^(%a+)%-(.+)$")if P~="CTRL"and(P~="ALT"and P~="SHIFT")then break end Y[P]=true j=X end if j=="NUMPADPLUS"then j="NUMPADADD"end if j=="NUMPADMINUS"then j="NUMPADSUBTRACT"end return((Y.CTRL and"CTRL-"or""))..(((Y.ALT and"ALT-"or""))..(((Y.SHIFT and"SHIFT-"or""))..j))end local j={"F6","F7","F8";"F9","F10";"F11";"F12";"8";"9","0","-";"=";"[","]",";";"\'",",";".","\\","UP","DOWN","LEFT";"RIGHT";"INSERT";"DELETE","HOME";"END"}P8BA6426E.ACTION_KEY_ORDER={}P8BA6426E.VERIFIED_ACTION_KEYS={}for P,j in ipairs(j)do table.insert(P8BA6426E.ACTION_KEY_ORDER,j)end for P,Y in ipairs({"CTRL","ALT"})do for P,j in ipairs(j)do table.insert(P8BA6426E.ACTION_KEY_ORDER,Y..("-"..j))end end for P,j in ipairs(P)do table.insert(P8BA6426E.VERIFIED_ACTION_KEYS,j)end for P=1,23,1 do table.insert(P8BA6426E.VERIFIED_ACTION_KEYS,"CTRL-"..j[P])end for P=7,12,1 do table.insert(P8BA6426E.VERIFIED_ACTION_KEYS,"ALT-F"..P)end for P,j in ipairs({"8","9","0",";","\'"})do table.insert(P8BA6426E.VERIFIED_ACTION_KEYS,"ALT-"..j)end